public class SarifDataType : SarifObject {
	
	public SarifDataType(IsfObject obj, IsfDataTypeWriter writer) : base("DataType", DataTypesSarifMgr.KEY, writer.getTree(obj))
    {
		message.addProperty("text", objToMessage(obj));
	}

	private string objToMessage(IsfObject obj) {
		if (obj is IsfComposite) {
			return ((IsfComposite) obj).kind.equals("struct") ? "DT.Struct" : "DT.Union";
		}
		if (obj is IsfEnum) {
			return "DT.Enum";
		}
		if (obj is IsfFunction) {
			return "DT.Function";
		}
		if (obj is IsfTypedefBase ||
			//obj instanceof IsfTypedefIntegral ||
			obj is IsfTypedefPointer ||
			obj is IsfTypedefUser) {
			return "DT.Typedef";
		}
		if (obj is IsfTypedObject) {
			return "DT.TypedObject";
		}
		if (obj is IsfBuiltIn) {
			return "DT.Builtin";
		}
		return "DT.Base";
	}

}
